package main

import (
	"fmt"
	"log"
	"os"
	"os/signal"
	"syscall"

	// Provides APIs for attaching eBPF programs
	// to Linux kernel hooks.
	"github.com/cilium/ebpf/link"
)

func main() {

    /*
     * STEP 1: Load the eBPF program into kernel memory.
     *
     * execObjects is generated by bpf2go.
     * It contains references to our eBPF programs
     * and maps.
     */
    var objs execObjects

    /*
     * loadExecObjects() is also generated by bpf2go.
     *
     * It loads the embedded eBPF bytecode into the
     * Linux kernel using the bpf() system call.
     *
     * The kernel verifier checks the program before
     * accepting it.
     */
    if err := loadExecObjects(&objs, nil); err != nil {
        log.Fatal("loading eBPF:", err)
    }

    /*
     * Release the loaded eBPF object handles when
     * main() exits.
     *
     * The kernel frees each object once no
     * references remain.
     */
    defer objs.Close()

    fmt.Println("eBPF program loaded into kernel memory")

    /*
     * STEP 2: Attach the program to a kernel hook.
     *
     * A loaded eBPF program doesn't automatically
     * execute. It must be attached to an appropriate
     * hook.
     *
     * Here we attach to the sched_process_exec
     * tracepoint.
     */
    tp, err := link.Tracepoint(
        "sched",             // Tracepoint category
        "sched_process_exec", // Tracepoint name
        objs.TraceExec,      // Our loaded eBPF program
        nil,                 // Default attachment options
    )
    if err != nil {
        log.Fatal("attaching tracepoint:", err)
    }

    /*
     * Detach the eBPF program when main() exits.
     *
     * Closing the unpinned link removes this
     * tracepoint attachment.
     */
    defer tp.Close()

    fmt.Println("KernelScope is watching processes...")
    fmt.Println("Press Ctrl+C to stop")

    /*
     * STEP 3: Wait for a shutdown signal.
     *
     * The eBPF program now executes independently
     * inside the Linux kernel whenever the
     * tracepoint fires.
     *
     * Go does not call trace_exec() for each event.
     */
    stop := make(chan os.Signal, 1)

    // Forward Ctrl+C and termination signals
    // to our Go channel.
    signal.Notify(
        stop,
        os.Interrupt,
        syscall.SIGTERM,
    )
    defer signal.Stop(stop)

    // Block until a shutdown signal arrives.
    <-stop

    /*
     * When main() returns, deferred cleanup runs:
     *
     * 1. tp.Close() detaches the tracepoint.
     * 2. objs.Close() releases eBPF object handles.
     *
     * Because we aren't pinning anything, the
     * program can be unloaded when its remaining
     * kernel references are released.
     */
}
